115	    private void rejectMissingOrBlankFields(OwnerFieldsDto ownerFieldsDto) {
116	        List<String> missing = new ArrayList<>();
117	        if (isBlank(ownerFieldsDto.getFirstName())) {
118	            missing.add("firstName");
119	        }
120	        if (isBlank(ownerFieldsDto.getLastName())) {
121	            missing.add("lastName");
122	        }
123	        if (isBlank(ownerFieldsDto.getAddress())) {
124	            missing.add("address");
125	        }
126	        if (isBlank(ownerFieldsDto.getCity())) {
127	            missing.add("city");
128	        }
129	        if (isBlank(ownerFieldsDto.getTelephone())) {
130	            missing.add("telephone");
131	        }
132	        if (!missing.isEmpty()) {
133	            throw new MissingOwnerFieldsException(missing);
134	        }
135	    }
