141	    /**
142	     * Normalizes an owner's telephone on create by stripping every non-digit character and
143	     * requiring exactly ten digits to remain. The stripped, digits-only value is what gets
144	     * stored and returned. A value that does not reduce to exactly ten digits is rejected via
145	     * {@link InvalidTelephoneException}, which the exception handler translates to a 400.
146	     */
147	    private static String normalizeTelephone(String telephone) {
148	        String digits = telephone == null ? "" : telephone.replaceAll("\\D", "");
149	        if (digits.length() != 10) {
150	            throw new InvalidTelephoneException(telephone);
151	        }
152	        return digits;
153	    }
