165	     * lower-cased so it is stored and returned in canonical form. An invalid value is rejected via
166	     * {@link InvalidEmailException}, which the exception handler translates to a 400.
167	     */
168	    private static String normalizeEmail(String email) {
169	        if (email == null) {
170	            return null;
171	        }
172	        if (!EMAIL_PATTERN.matcher(email).matches()) {
173	            throw new InvalidEmailException(email);
174	        }
175	        return email.toLowerCase(Locale.ROOT);
